class FMDataHelperWF
{
    private static 
    str FMVehicleMaintenanceProjectionDataSource = 'FMVehicleMaintenance_1';
    private static 
    str FMVehicleMaintenanceDocument = "FMWorkflowDocument";
    private static
    SysDictWorkflowType workflowMetadata = null;

}

